(() => {
  if (window.__tuneRiftAccountMenuInstalled) return;
  window.__tuneRiftAccountMenuInstalled = true;

  const NEW_DESIGN_KEY = 'tunerift:use-new-design';
  const OVERLAY_ID = 'tunerift-mod-settings-overlay';
  const MENU_ID = 'tunerift-mod-account-entry';
  const MENU_VERSION = 'v10-no-menu-icon-ipc-new-design';
  const LOGO_DATA = 'data:image/png;base64,';
  let latestState = { settings: {}, addons: [] };
  let reportedMissingAnchor = false;
  let pendingOpen = false;

  const style = document.createElement('style');
  style.textContent = `
    #${MENU_ID}{display:flex!important;align-items:center!important;gap:12px!important;width:100%!important;min-height:48px!important;padding:10px 14px!important;border:0!important;border-radius:12px!important;background:transparent!important;color:inherit!important;font:inherit!important;text-align:left!important;cursor:pointer!important;box-sizing:border-box!important}
    #${MENU_ID}:hover{background:rgba(127,127,127,.12)!important}
    #${MENU_ID} .tr-menu-logo{display:block!important;width:24px!important;height:24px!important;object-fit:contain!important;flex:0 0 24px!important}
    #${MENU_ID} .tr-menu-text{font-weight:400!important;line-height:20px!important}
    
    #${OVERLAY_ID}{position:fixed!important;inset:0!important;z-index:2147483646!important;display:flex!important;align-items:center!important;justify-content:center!important;padding:20px!important;background:rgba(0,0,0,.48)!important;backdrop-filter:blur(8px)!important;box-sizing:border-box!important}
    #${OVERLAY_ID} .tr-card{width:min(440px,100%)!important;max-height:min(680px,calc(100vh - 40px))!important;overflow:auto!important;border:1px solid rgba(255,255,255,.14)!important;border-radius:22px!important;background:#242424!important;color:#f5f5f5!important;box-shadow:0 24px 70px rgba(0,0,0,.45)!important;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Arial,sans-serif!important}
    #${OVERLAY_ID} .tr-header{display:flex!important;align-items:center!important;justify-content:space-between!important;padding:20px 20px 14px!important}
    #${OVERLAY_ID} .tr-brand{display:flex!important;align-items:center!important;gap:11px!important;font-size:19px!important;font-weight:400!important}
    #${OVERLAY_ID} .tr-logo{display:block!important;width:32px!important;height:32px!important;object-fit:contain!important}
    #${OVERLAY_ID} .tr-close{width:32px!important;height:32px!important;border:0!important;border-radius:10px!important;background:rgba(255,255,255,.08)!important;color:#fff!important;font-size:22px!important;line-height:28px!important;cursor:pointer!important}
    #${OVERLAY_ID} .tr-subtitle{margin:0!important;padding:0 20px 18px!important;color:rgba(255,255,255,.62)!important;font-size:13px!important;line-height:18px!important}
    #${OVERLAY_ID} .tr-section{margin:0 12px 12px!important;padding:4px!important;border-radius:16px!important;background:rgba(255,255,255,.06)!important}
    #${OVERLAY_ID} .tr-option{display:flex!important;align-items:center!important;gap:12px!important;padding:13px 12px!important;border-radius:12px!important}
    #${OVERLAY_ID} .tr-option:not(:last-child){border-bottom:1px solid rgba(255,255,255,.07)!important}
    #${OVERLAY_ID} .tr-option-main{flex:1!important;min-width:0!important}
    #${OVERLAY_ID} .tr-option-title{display:block!important;font-size:14px!important;font-weight:400!important;line-height:18px!important}
    #${OVERLAY_ID} .tr-option-note{display:block!important;margin-top:3px!important;color:rgba(255,255,255,.55)!important;font-size:12px!important;line-height:16px!important}
    #${OVERLAY_ID} .tr-switch{appearance:none!important;position:relative!important;display:inline-block!important;width:42px!important;height:25px!important;min-width:42px!important;margin:0!important;border:0!important;border-radius:999px!important;background:#5d5d5d!important;cursor:pointer!important;transition:background .15s ease!important}
    #${OVERLAY_ID} .tr-switch:checked{background:#ffcc00!important}
    #${OVERLAY_ID} .tr-switch::after{content:''!important;position:absolute!important;top:3px!important;left:3px!important;width:19px!important;height:19px!important;border-radius:50%!important;background:#fff!important;box-shadow:0 1px 3px rgba(0,0,0,.28)!important;transition:transform .15s ease!important}
    #${OVERLAY_ID} .tr-switch:checked::after{transform:translateX(17px)!important}
    #${OVERLAY_ID} .tr-footer{padding:4px 20px 20px!important;color:rgba(255,255,255,.42)!important;font-size:11px!important;line-height:15px!important}
  `;
  document.head.appendChild(style);

  function post(data) {
    const target = window.top && window.top !== window ? window.top : window;
    target.postMessage(data, '*');
  }

  function getAddonEnabled(id) {
    const addon = latestState.addons.find(item => item.id === id);
    return Boolean(addon?.enabled);
  }

  function closeDialog() {
    document.getElementById(OVERLAY_ID)?.remove();
  }

  function setAddonState(id, value) {
    const addon = latestState.addons.find(item => item.id === id);
    if (addon) addon.enabled = Boolean(value);
    post({ type: 'tunerift:mod-settings:set', key: 'addon', id, value: Boolean(value) });
  }

  function addOption(parent, { title, note, checked, onChange }) {
    const row = document.createElement('label');
    row.className = 'tr-option';
    const main = document.createElement('span');
    main.className = 'tr-option-main';
    const titleNode = document.createElement('span');
    titleNode.className = 'tr-option-title';
    titleNode.textContent = title;
    const noteNode = document.createElement('span');
    noteNode.className = 'tr-option-note';
    noteNode.textContent = note;
    main.append(titleNode, noteNode);
    const control = document.createElement('input');
    control.className = 'tr-switch';
    control.type = 'checkbox';
    control.checked = checked;
    control.addEventListener('change', () => onChange(control.checked));
    row.append(main, control);
    parent.appendChild(row);
  }

  function openDialog() {
    closeDialog();
    const overlay = document.createElement('div');
    overlay.id = OVERLAY_ID;
    const card = document.createElement('div');
    card.className = 'tr-card';
    card.addEventListener('click', event => event.stopPropagation());

    const header = document.createElement('div');
    header.className = 'tr-header';
    const brand = document.createElement('div');
    brand.className = 'tr-brand';
    const logo = document.createElement('img');
    logo.className = 'tr-logo';
    logo.src = LOGO_DATA;
    logo.alt = 'TuneRift Mod';
    const name = document.createElement('span');
    name.textContent = 'TuneRift Mod';
    brand.append(logo, name);
    const close = document.createElement('button');
    close.className = 'tr-close';
    close.type = 'button';
    close.textContent = '×';
    close.addEventListener('click', closeDialog);
    header.append(brand, close);

    const subtitle = document.createElement('p');
    subtitle.className = 'tr-subtitle';
    subtitle.textContent = 'Настройки TuneRift сохраняются локально и применяются после перезагрузки страницы, когда это требуется.';

    const section = document.createElement('div');
    section.className = 'tr-section';
    addOption(section, {
      title: 'Discord Rich Presence',
      note: 'Показывает текущий трек и таймлайн в Discord.',
      checked: Boolean(latestState.settings.discordEnabled),
      onChange: value => {
        latestState.settings.discordEnabled = Boolean(value);
        post({ type: 'tunerift:mod-settings:set', key: 'discordEnabled', value: Boolean(value) });
      }
    });
    addOption(section, {
      title: 'Маркировка E',
      note: 'Заменяет значок 18+ на компактную букву E.',
      checked: getAddonEnabled('tunerift-explicit-e-mark'),
      onChange: value => setAddonState('tunerift-explicit-e-mark', value)
    });
    addOption(section, {
      title: 'Apple Music lyrics',
      note: 'Размытие неактивных строк на экране синхронизированной лирики.',
      checked: getAddonEnabled('8c4b0e14-e365-4160-ab4c-8c26cf3fa84e'),
      onChange: value => setAddonState('8c4b0e14-e365-4160-ab4c-8c26cf3fa84e', value)
    });

    const footer = document.createElement('div');
    footer.className = 'tr-footer';
    footer.textContent = 'TuneRift Mod · настройки не передаются Яндекс Музыке.';
    card.append(header, subtitle, section, footer);
    overlay.appendChild(card);
    overlay.addEventListener('click', closeDialog);
    document.body.appendChild(overlay);
  }

  function findAppearanceMenu() {
    const leaf = [...document.querySelectorAll('body *')].find(el =>
      el.childElementCount === 0 && el.textContent.trim() === 'Внешний вид'
    );
    if (!leaf) return null;
    const row = leaf.closest('[role="button"], a, button') || leaf.parentElement;
    if (!row || row === document.body) return null;
    return { row, menu: row.parentElement };
  }

  function ensureMenuItem() {
    if (document.getElementById(MENU_ID)) return;
    const target = findAppearanceMenu();
    if (!target) {
      if (!reportedMissingAnchor) {
        reportedMissingAnchor = true;
        console.warn('[TuneRift Mod Menu] не нашёл пункт «Внешний вид»');
      }
      return;
    }
    reportedMissingAnchor = false;

    // Clone the real appearance row and insert the TuneRift item directly after it.
    const entry = target.row.cloneNode(true);
    entry.removeAttribute('id');
    entry.removeAttribute('data-log');
    entry.removeAttribute('data-testid');
    entry.removeAttribute('aria-haspopup');
    entry.removeAttribute('aria-expanded');
    entry.id = MENU_ID;
    entry.setAttribute('role', 'button');
    entry.setAttribute('tabindex', '0');
    entry.innerHTML = '<span class="tr-menu-text">TuneRift Mod</span>';
    entry.dataset.tuneriftMenuVersion = MENU_VERSION;
    const open = () => {
      pendingOpen = true;
      post({ type: 'tunerift:mod-settings:get' });
    };
    entry.addEventListener('click', event => { event.preventDefault(); event.stopPropagation(); open(); });
    entry.addEventListener('keydown', event => {
      if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); open(); }
    });
    target.row.insertAdjacentElement('afterend', entry);
    console.log('[TuneRift Mod Menu] inserted', MENU_VERSION);
  }

  window.addEventListener('message', event => {
    if (!event.data) return;
    const fromParent = window.top && event.source === window.top;
    if (event.source !== window && !fromParent) return;
    if (event.data.type === 'tunerift:mod-settings:state') {
      latestState = event.data;
      if (document.getElementById(OVERLAY_ID) || pendingOpen) {
        pendingOpen = false;
        openDialog();
      }
    }
    if (event.data.type === 'tunerift:mod-settings:error') {
      console.warn('[TuneRift Mod Menu]', event.data.message);
    }
  });

  const observer = new MutationObserver(ensureMenuItem);
  observer.observe(document.documentElement, { childList: true, subtree: true });
  setInterval(ensureMenuItem, 700);
  ensureMenuItem();
  console.log('[TuneRift Mod Menu] активен');
})();
